 assets.append({'key':k,'label_ja':label,'description_ja':desc,'path':path,'size_px':[512,64],'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'recommended_event':EVENTS[k],'anchor_px':[32,32],'frame_count':8,'total_duration_ms':start,'loop':False,'clear_frame_index':7,'clear_on_finish':True,'frames':frames})
